"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[8314],{87394:e=>{e.exports=JSON.parse('{"tag":{"label":"Pipelines","permalink":"/datagol-knowlegde-base-v1/docs/tags/pipelines","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":3,"items":[{"id":"Lakehouse/Orchestrations/About orchestration","title":"About orchestration","description":"Orchestration in DataGOL allows you to define and manage the execution order of multiple pipelines. This is crucial when you have dependencies between pipelines, where one pipeline needs to complete successfully before another can begin. Without orchestration, scheduling pipelines to run independently might lead to failures or unexpected results if a dependent pipeline runs before its required data is ready.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Orchestrations/about-orchestration"},{"id":"Lakehouse/Pipelines/Creating Dedup pipeline","title":"Creating Dedup pipeline","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Pipelines.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Pipelines/creating-dedup-pipeline"},{"id":"Lakehouse/Lakehouse workflow","title":"Lakehouse workflow","description":"1.  Connecting to data Sources: The journey begins with establishing connections to various data sources. Think of these as the starting points where your raw data lives. These could be relational databases like SQL Server, PostgreSQL, cloud data warehouses like Redshift, or even file storage systems such as S3 or Azure blob.. The crucial function here is to enable the Lakehouse to access the data that needs to be processed and analyzed.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/lakehouse-workflow"}],"unlisted":false}}')}}]);